const main=document.querySelector('main');
const seeds=[
 {id:'cian-msk-resale',name:'CIAN — Москва, вторичка',format:'cian',url:'https://cian.ru/export/kvadrat-msk-resale.xml',schedule:'Каждые 30 минут',lastSync:'8 минут назад',objects:1240,status:'active',errors:0},
 {id:'cian-msk-new',name:'CIAN — Москва, новостройки',format:'cian',url:'https://cian.ru/export/kvadrat-msk-new.xml',schedule:'Каждый час',lastSync:'34 минуты назад',objects:862,status:'active',errors:0},
 {id:'avito-rent',name:'Avito — Аренда квартир',format:'avito',url:'https://autoload.avito.ru/kvadrat-rent.xml',schedule:'Каждые 2 часа',lastSync:'1 час назад',objects:318,status:'error',errors:12},
 {id:'yrl-comm',name:'Яндекс YRL — Коммерция',format:'yrl',url:'https://feed.kvadrat.ru/yandex-commerce.yrl',schedule:'Ежедневно, 05:00',lastSync:'Сегодня, 05:00',objects:143,status:'active',errors:0},
 {id:'cian-zagorod',name:'CIAN — Загород, Московская обл.',format:'cian',url:'https://cian.ru/export/kvadrat-zagorod.xml',schedule:'Вручную',lastSync:'3 дня назад',objects:76,status:'paused',errors:0},
 {id:'avito-garage',name:'Avito — Гаражи и машиноместа',format:'avito',url:'',schedule:'Не задано',lastSync:'Не запускался',objects:0,status:'draft',errors:0}
];
let feeds=structuredClone(seeds),query='',filter='all',format='all';
const fmt={cian:'CIAN XML',avito:'Avito',yrl:'Яндекс YRL'};
const statuses={active:['Активен','ok'],error:['Есть ошибки','error'],paused:['На паузе',''],draft:['Черновик','']};
const nf=n=>Number(n).toLocaleString('ru-RU');
const badge=f=>`<span class="badge ${statuses[f.status][1]}">${statuses[f.status][0]}</span>`;
function renderList(){document.title='Импорт-фиды — Квадрат';document.querySelector('#breadcrumb').textContent='Импорт-фиды';main.innerHTML=`<div class="page-head"><div><div class="eyebrow">КАТАЛОГ</div><h1>Импорт-фиды</h1><p>Источники объявлений и результаты синхронизации</p></div><a class="btn primary" href="#new">＋ Добавить фид</a></div><div class="stats"><button class="stat" data-filter="all"><span>Всего источников</span><strong>${feeds.length}</strong></button><button class="stat" data-filter="active"><span>Активные</span><strong>${feeds.filter(f=>f.status==='active').length}</strong></button><div class="stat"><span>Объектов в каталоге</span><strong>${nf(feeds.reduce((s,f)=>s+f.objects,0))}</strong></div><button class="stat attention" data-filter="error"><span>Требуют внимания</span><strong>${feeds.filter(f=>f.status==='error').length}</strong></button></div><div class="toolbar"><label class="search"><span aria-hidden="true">⌕</span><input id="search" type="search" placeholder="Название или адрес фида" aria-label="Поиск фидов" value="${e(query)}"></label><label class="row small">Формат <select id="format"><option value="all">Все форматы</option>${Object.entries(fmt).map(([k,v])=>`<option value="${k}" ${format===k?'selected':''}>${v}</option>`).join('')}</select></label></div><div class="filters">${[['all','Все'],['error','С ошибками'],['active','Активные'],['paused','На паузе'],['draft','Черновики']].map(([k,v])=>`<button class="chip" data-filter="${k}" aria-pressed="${filter===k}">${v} <small>${feeds.filter(f=>k==='all'||f.status===k).length}</small></button>`).join('')}</div><div class="panel" id="results"></div>`;drawRows();main.querySelector('#search').oninput=ev=>{query=ev.target.value;drawRows()};main.querySelector('#format').onchange=ev=>{format=ev.target.value;drawRows()};main.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;renderList()});}
function drawRows(){const rows=feeds.filter(f=>(filter==='all'||filter===f.status)&&(format==='all'||format===f.format)&&(f.name+' '+f.url).toLowerCase().includes(query.toLowerCase().trim()));document.querySelector('#results').innerHTML=rows.length?`<div class="table-scroll"><table class="feed-table"><thead><tr><th>Источник</th><th>Состояние</th><th>Последний импорт</th><th>Расписание</th><th>Объектов</th><th><span class="small">Действия</span></th></tr></thead><tbody>${rows.map(f=>`<tr><td><a class="feed-name" href="#feed/${f.id}/settings">${e(f.name)}</a><div class="source-url" title="${e(f.url)}">${e(f.url||'Источник ещё не указан')}</div><span class="format-tag">${fmt[f.format]}</span></td><td>${badge(f)}</td><td><span class="sync-label">${f.lastSync}</span>${f.errors?`<a class="result-link" href="#feed/${f.id}/check">Ошибок: ${f.errors} · Разобрать →</a>`:`<div class="small muted">${f.status==='draft'?'Нужна настройка':f.status==='paused'?'Автоимпорт приостановлен':'Без ошибок'}</div>`}</td><td>${f.schedule}</td><td><strong>${nf(f.objects)}</strong></td><td><a class="btn square" href="#feed/${f.id}/settings" aria-label="Настроить ${e(f.name)}">Настроить</a></td></tr>`).join('')}</tbody></table></div><div class="table-foot"><span>Показано ${rows.length} из ${feeds.length} источников</span><span>Состояние демонстрационного каталога</span></div>`:`<div class="empty"><h2>Фиды не найдены</h2><p>Измените запрос или сбросьте фильтры.</p><button id="reset" class="btn">Сбросить фильтры</button></div>`;const reset=main.querySelector('#reset');if(reset)reset.onclick=()=>{query='';filter='all';format='all';renderList()};}
const response=await fetch('feed-reference.json');
if(!response.ok){main.innerHTML='<div class="panel empty"><h1>Не удалось загрузить макет</h1><p>Обновите страницу, чтобы повторить загрузку образцов.</p></div>';throw Error('Не удалось загрузить образцы');}
const reference=await response.json(),fields=reference.tree.flatMap(g=>g.fields),byType=Object.fromEntries(reference.catalog.flatMap(g=>g.items.map(t=>[t.type,t])));
const storageKey='kvadrat.feed-prototype.v1';
let draft=null,baseline='',tab='settings',selected='price',sampleIndex=0,fieldQuery='',fieldFilter='all',undo=[],toastTimer,currentHash=location.hash||'#list',busy=false;
const types={string:'Текст',number:'Число',enum:'Справочник',bool:'Да / Нет',collection:'Список',geo:'Координаты',ref:'Ссылка'};
const typeLabels={cosmetic:'Косметический',design:'Дизайнерский',euro:'Евроремонт',no:'Нет',combined:'Смежные',separate:'Изолированные',both:'Смешанные',street:'Улица',yard:'Двор',yardAndStreet:'Улица и двор',brick:'Кирпич',monolith:'Монолит',panel:'Панель',block:'Блоки',wood:'Дерево',townhouse:'Таунхаус',land:'Участок',retail:'Торговое помещение',warehouse:'Склад',true:'Да',false:'Нет',error:'Показать ошибку',sale:'Продажа',rent_long:'Долгосрочная аренда',rent_daily:'Посуточная аренда',flat:'Квартира',room:'Комната',house:'Дом',office:'Офис',garage:'Гараж',RUB:'Рубли',USD:'Доллары',KZT:'Тенге',auto:'Автоматически',comma:'Запятая',dot:'Точка',round:'Обычное',floor:'Вниз',ceil:'Вверх',lower:'Нижний регистр',upper:'Верхний регистр',ucfirst:'С заглавной',title:'Каждое слово с заглавной'};
function makeFeed(seed){const isNew=seed.status==='draft';return {name:'',format:'cian',url:'',encoding:'auto',sourceKind:'url',owner:'Квадрат — головной офис',schedMode:'interval',interval:'30',time:'05:00',days:[1,2,3,4,5,6,0],timezone:'Europe/Moscow',fetchMedia:true,mediaLimit:30,archiveRemoved:true,archiveAfter:2,geocode:false,maxSize:50,timeout:120,maxErrors:50,fileName:'',sampleLoaded:!isNew,samples:isNew?[]:clone(reference.formats[seed.format].samples),mapping:isNew?{}:clone(reference.formats[seed.format].preset),checked:false,history:[],...seed};}
feeds=seeds.map(makeFeed);feeds[1].interval='60';feeds[2].interval='120';feeds[3].schedMode='daily';feeds[4].schedMode='manual';feeds[5].schedMode='manual';
try{const saved=JSON.parse(localStorage.getItem(storageKey)||'null');if(saved?.version===1&&Array.isArray(saved.feeds)&&saved.feeds.every(f=>f&&typeof f.id==='string'&&f.mapping&&Array.isArray(f.samples)&&Object.hasOwn(fmt,f.format)&&Object.hasOwn(statuses,f.status))){feeds=saved.feeds.map(makeFeed);}}catch{setTimeout(()=>toast('Сохранённые данные не прочитаны. Загружены исходные примеры.'),0);}
function toast(text){const box=document.querySelector('#toast');box.textContent=text;box.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.hidden=true,4500);}
function persist(){try{localStorage.setItem(storageKey,JSON.stringify({version:1,feeds}));return true;}catch{toast('Не удалось сохранить: хранилище браузера недоступно или заполнено. Изменения остались на экране.');return false;}}
function changed(){return !!draft&&JSON.stringify(draft)!==baseline;}
function mark(invalidate=true){if(invalidate)draft.checked=false;const status=document.querySelector('#save-state');if(status){status.textContent=changed()?'Есть несохранённые изменения':'Все изменения сохранены в браузере';status.classList.toggle('unsaved',changed());}document.querySelectorAll('[data-save],[data-action=discard]').forEach(b=>b.disabled=!changed());}
function report(){return assess(fields,draft.mapping,draft.samples);}
function schedule(f){return f.schedMode==='manual'?'Вручную':f.schedMode==='daily'?`${f.days.length===7?'Ежедневно':f.days.length===5&&[1,2,3,4,5].every(d=>f.days.includes(d))?'По будням':f.days.length+' дн./нед.'}, ${f.time}`:f.interval==='60'?'Каждый час':`Каждые ${Number(f.interval)>=60?Number(f.interval)/60+' ч':f.interval+' мин'}`;}
function sourceValid(){if(draft.sourceKind==='file')return !!draft.fileName;try{return ['http:','https:'].includes(new URL(draft.url).protocol);}catch{return false;}}
function configErrors(){const errors=[];if(!draft.name.trim())errors.push({id:'name',text:'Укажите название фида.'});if(!sourceValid())errors.push({id:draft.sourceKind==='file'?'xml-file':'url',text:draft.sourceKind==='file'?'Выберите XML-файл.':'Укажите полный HTTP(S)-адрес фида.'});if(draft.schedMode==='daily'&&(!draft.days.length||!/^\d{2}:\d{2}$/.test(draft.time)))errors.push({id:'time',text:'Выберите время и хотя бы один день запуска.'});for(const [id,min,max,title] of [['mediaLimit',1,100,'Число фотографий'],['archiveAfter',1,30,'Число импортов до архивации'],['maxSize',1,100,'Размер файла'],['timeout',5,600,'Время ожидания'],['maxErrors',1,1000,'Лимит ошибок']])if(!Number.isInteger(Number(draft[id]))||Number(draft[id])<min||Number(draft[id])>max)errors.push({id,text:`${title}: укажите целое число от ${min} до ${max}.`});return errors;}
function save(silent=false){if(!draft.name.trim()){tab='settings';renderEditor();showErrors([{id:'name',text:'Укажите название фида, чтобы сохранить черновик.'}]);return false;}const wasNew=draft.id==='new';if(wasNew)draft.id=crypto.randomUUID();draft.name=draft.name.trim();draft.schedule=schedule(draft);const previous=clone(feeds),index=feeds.findIndex(f=>f.id===draft.id);if(index<0)feeds.push(clone(draft));else feeds[index]=clone(draft);if(!persist()){feeds=previous;if(wasNew)draft.id='new';return false;}baseline=JSON.stringify(draft);if(wasNew){history.replaceState(null,'',`#feed/${draft.id}/${tab}`);currentHash=location.hash;renderEditor();}mark(false);if(!silent)toast('Изменения сохранены в этом браузере');return true;}
function showErrors(errors){const box=document.querySelector('#form-errors');if(!box){toast(errors[0].text);return;}box.hidden=false;box.innerHTML=`<strong>Проверьте настройки</strong><ul>${errors.map(x=>`<li><a href="#${x.id}" data-focus="${x.id}">${e(x.text)}</a></li>`).join('')}</ul>`;box.querySelectorAll('[data-focus]').forEach(a=>a.onclick=ev=>{ev.preventDefault();const input=document.getElementById(a.dataset.focus);input?.closest('details')?.setAttribute('open','');input?.focus()});box.focus();errors.forEach(x=>{const el=document.getElementById(x.id);if(el){el.setAttribute('aria-invalid','true');el.setAttribute('aria-describedby','form-errors');}});}
function dialog(title,body,buttons){const dlg=document.querySelector('#dialog');dlg.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${e(title)}</h2><button class="btn square" aria-label="Закрыть" data-close>×</button></div><div class="dialog-body">${body}</div><div class="dialog-actions">${buttons.map((b,i)=>`<button class="btn ${b.primary?'primary':''} ${b.danger?'danger':''}" data-dialog-action="${i}">${e(b.label)}</button>`).join('')}</div>`;dlg.querySelector('[data-close]').onclick=()=>dlg.close();dlg.querySelectorAll('[data-dialog-action]').forEach(b=>b.onclick=()=>{dlg.close();buttons[Number(b.dataset.dialogAction)].action?.()});if(!dlg.open)dlg.showModal();return dlg;}
function remember(){undo.push(clone(draft.mapping));if(undo.length>30)undo.shift();}
function editMapping(action){remember();draft.mapping[selected]??={mode:'empty',source:'',const:'',steps:[]};action();mark();renderEditor();}
function fieldMapping(){return draft.mapping[selected]??{mode:'empty',source:'',const:'',steps:[]};}
function go(hash){if(location.hash!==hash)location.hash=hash;else route();}
function route(){const parts=location.hash.slice(1).split('/'),id=parts[0]==='new'?'new':parts[0]==='feed'?parts[1]:null;currentHash=location.hash||'#list';if(!id){draft=null;baseline='';renderList();return;}if(!draft||draft.id!==id){if(id==='new')draft=makeFeed({id:'new',name:'',format:'cian',url:'',status:'draft',objects:0,errors:0,lastSync:'Не запускался',schedule:'Не задано'});else{const found=feeds.find(f=>f.id===id);if(!found){main.innerHTML='<div class="empty"><h1>Фид не найден</h1><p>Он отсутствует в локальном макете.</p><a class="btn" href="#list">К списку фидов</a></div>';return;}draft=clone(found);}baseline=JSON.stringify(draft);selected='price';sampleIndex=0;undo=[];fieldFilter='all';fieldQuery='';}tab=['settings','mapping','check'].includes(parts[2])?parts[2]:'settings';renderEditor();}
document.addEventListener('click',ev=>{const a=ev.target.closest('a');if(ev.defaultPrevented||!a||ev.ctrlKey||ev.metaKey||ev.shiftKey)return;const href=a.getAttribute('href');if(href==='#main'){ev.preventDefault();main.focus();return;}if(!changed())return;const same=href?.startsWith(`#feed/${draft.id}/`)||draft.id==='new'&&href?.startsWith('#feed/new/');if(same)return;ev.preventDefault();dialog('Сохранить изменения?',`<p>Настройки фида «${e(draft.name||'Новый фид')}» изменены.</p>`,[{label:'Остаться'},{label:'Не сохранять',action:()=>{draft=null;baseline='';location.href=href}},{label:'Сохранить и перейти',primary:true,action:()=>{if(save(true)){draft=null;baseline='';location.href=href}}}]);});
window.addEventListener('beforeunload',ev=>{if(changed()){ev.preventDefault();ev.returnValue='';}});
window.addEventListener('hashchange',()=>{const incoming=location.hash,parts=incoming.slice(1).split('/');if(changed()&&!(parts[0]==='feed'&&parts[1]===draft.id)&&!(parts[0]==='new'&&draft.id==='new')){history.replaceState(null,'',currentHash);dialog('Уйти без сохранения?',`<p>Изменения текущего фида ещё не сохранены.</p>`,[{label:'Остаться'},{label:'Не сохранять',action:()=>{draft=null;baseline='';go(incoming)}},{label:'Сохранить и перейти',primary:true,action:()=>{if(save(true)){draft=null;baseline='';go(incoming)}}}]);return;}route();});
function renderEditor(){document.title=(draft.name||'Новый фид')+' — Квадрат';document.querySelector('#breadcrumb').textContent=draft.name||'Новый фид';const r=report();main.className='editor-main';const ready=draft.sampleLoaded&&r.covered===r.required&&configErrors().length===0;main.innerHTML=`<a class="back" href="#list">← Все импорт-фиды</a><div class="page-head editor-head"><div><div class="row"><span class="format-tag">${fmt[draft.format]}</span>${badge(draft)}</div><h1>${e(draft.name||'Новый фид')}</h1></div><div class="row">${['active','error'].includes(draft.status)?'<button class="btn" data-action="pause">Ⅱ Приостановить</button>':`<button class="btn" data-action="activate">▷ ${draft.status==='paused'?'Возобновить':'Активировать'}</button>`}<button class="btn primary" data-action="run" ${busy?'disabled':''}>▷ Демоимпорт</button></div></div><nav class="editor-tabs" aria-label="Настройка фида">${[['settings','1','Источник и настройки'],['mapping','2','Маппинг полей'],['check','3','Проверка образца']].map(([k,n,label])=>`<a href="#feed/${draft.id}/${k}" ${tab===k?'aria-current="page"':''}><span class="tab-number">${n}</span>${label}${k==='check'&&r.issues.length?`<span class="tab-count">${r.issues.length}</span>`:''}</a>`).join('')}</nav><div id="editor-content">${tab==='settings'?settingsHtml():tab==='mapping'?mappingHtml(r):checkHtml(r)}</div><div class="save-bar"><div><span id="save-state" class="${changed()?'unsaved':''}">${changed()?'Есть несохранённые изменения':'Все изменения сохранены в браузере'}</span><small>${ready?'Обязательные поля заполнены на всём образце':!draft.sampleLoaded?'Сначала загрузите образец':`Обязательных полей: ${r.covered} из ${r.required}`}</small></div><div class="row"><button class="btn" data-action="discard" ${!changed()?'disabled':''}>Отменить изменения</button><button class="btn primary" data-save ${!changed()?'disabled':''}>Сохранить изменения</button></div></div>`;main.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>save());main.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));if(tab==='settings')bindSettings();if(tab==='mapping'&&draft.sampleLoaded)bindMapping();if(tab==='check')bindCheck();}
const input=(key,label,type='text',hint='',extra='')=>`<label class="field" for="${key}"><span>${label}</span><input id="${key}" data-config="${key}" type="${type}" value="${e(String(draft[key]??''))}" ${extra}>${hint?`<small>${hint}</small>`:''}</label>`;
const options=(items,value)=>Object.entries(items).map(([k,v])=>`<option value="${e(k)}" ${String(value)===k?'selected':''}>${e(v)}</option>`).join('');
const select=(key,label,items,hint='')=>`<label class="field" for="${key}"><span>${label}</span><select id="${key}" data-config="${key}">${options(items,draft[key])}</select>${hint?`<small>${hint}</small>`:''}</label>`;
const toggle=(key,title,desc)=>`<label class="toggle-row"><span><strong>${title}</strong><small>${desc}</small></span><input type="checkbox" role="switch" data-config="${key}" ${draft[key]?'checked':''} aria-label="${title}"></label>`;
function settingsHtml(){return `<div class="settings-layout"><div class="settings-form"><div id="form-errors" class="notice error" role="alert" tabindex="-1" hidden></div><section class="panel form-panel"><div class="section-title"><span class="section-icon">↗</span><div><h2>Источник данных</h2><p>Откуда получать объявления</p></div></div><div class="form-grid">${input('name','Название фида <span class="required">*</span>','text','Например, «CIAN — Москва, вторичка»','maxlength="120" required')}${select('owner','Владелец',{'Квадрат — головной офис':'Квадрат — головной офис','Агентство «Столица»':'Агентство «Столица»','Агентство «Юг»':'Агентство «Юг»'})}${select('format','Формат',fmt)}${select('encoding','Кодировка',{auto:'Определить автоматически',utf8:'UTF-8',win1251:'Windows-1251'})}</div><div class="field"><span>Способ загрузки</span><div class="segmented">${[['url','По ссылке'],['file','XML-файл']].map(([k,v])=>`<button type="button" data-source-kind="${k}" aria-pressed="${draft.sourceKind===k}">${v}</button>`).join('')}</div></div>${draft.sourceKind==='url'?input('url','Адрес XML-фида <span class="required">*</span>','url','В макете ссылка не запрашивается. Для проверки используется сохранённый демообразец.','placeholder="https://example.ru/feed.xml"'): `<label class="upload" for="xml-file"><strong>Выберите XML-файл</strong><span>${e(draft.fileName||'CIAN, Avito или Яндекс YRL · до 2 МБ')}</span><input id="xml-file" type="file" accept=".xml,.yrl,text/xml,application/xml"></label><p class="small muted">Файл разбирается в браузере. В образец попадут первые 20 записей.</p>`}<div class="source-check"><span class="badge ${draft.sampleLoaded?'ok':'warn'}">${draft.sampleLoaded?'✓ Образец загружен · '+draft.samples.length+' записи':'Образец не загружен'}</span><button class="btn" data-action="load-sample">${draft.sampleLoaded?'Обновить демообразец':'Загрузить демообразец'}</button></div></section><section class="panel form-panel"><div class="section-title"><span class="section-icon">◷</span><div><h2>Расписание</h2><p>Автоматический запуск или управление вручную</p></div></div><div class="segmented schedule-segment">${[['interval','По интервалу'],['daily','По дням недели'],['manual','Вручную']].map(([k,v])=>`<button data-schedule-mode="${k}" aria-pressed="${draft.schedMode===k}">${v}</button>`).join('')}</div>${draft.schedMode==='interval'?`<div class="form-grid">${select('interval','Запускать',{15:'Каждые 15 минут',30:'Каждые 30 минут',60:'Каждый час',120:'Каждые 2 часа',360:'Каждые 6 часов',720:'Каждые 12 часов',1440:'Раз в сутки'})}${select('timezone','Часовой пояс',{'Europe/Moscow':'Москва · UTC+3','Asia/Yekaterinburg':'Екатеринбург · UTC+5','Asia/Novosibirsk':'Новосибирск · UTC+7'})}</div>`:draft.schedMode==='daily'?`<div class="form-grid">${input('time','Время запуска','time')}${select('timezone','Часовой пояс',{'Europe/Moscow':'Москва · UTC+3','Asia/Yekaterinburg':'Екатеринбург · UTC+5','Asia/Novosibirsk':'Новосибирск · UTC+7'})}</div><div class="days" aria-label="Дни запуска">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map((d,i)=>`<button data-day="${(i+1)%7}" aria-pressed="${draft.days.includes((i+1)%7)}">${d}</button>`).join('')}</div>`:'<p class="muted small">Импорт запускается только по кнопке. Автоматического расписания нет.</p>'}</section><section class="panel form-panel"><div class="section-title"><span class="section-icon">≡</span><div><h2>Правила импорта</h2><p>Обновление объектов и работа с фотографиями</p></div></div>${toggle('fetchMedia','Загружать фотографии','Сохранить изображения из фида вместе с объявлением.')}${draft.fetchMedia?`<div class="indented">${input('mediaLimit','Максимум фото на объект','number','','min="1" max="100"')}</div>`:''}${toggle('archiveRemoved','Архивировать исчезнувшие объекты','Объявление архивируется, только если отсутствует в нескольких полных успешных импортах подряд.')}${draft.archiveRemoved?`<div class="indented">${input('archiveAfter','После скольких импортов без объекта','number','Защищает от случайной архивации при неполном фиде.','min="1" max="30"')}</div>`:''}${toggle('geocode','Определять координаты по адресу','Если в источнике нет координат. В макете сервис геокодирования не подключён.')}</section><details class="panel advanced"><summary>Дополнительные настройки</summary><div class="form-grid">${input('maxSize','Максимальный размер фида, МБ','number','','min="1" max="100"')}${input('timeout','Время ожидания, секунд','number','','min="5" max="600"')}${input('maxErrors','Остановить после ошибок','number','Число ошибок в одном импорте.','min="1" max="1000"')}</div><p class="small muted">В макете эти параметры сохраняются как настройки. Сетевые запросы и очереди не запускаются.</p></details></div><aside class="setup-summary panel"><h3>Готовность к импорту</h3><ol class="readiness"><li class="${draft.sampleLoaded?'done':''}"><span>${draft.sampleLoaded?'✓':'1'}</span><div><strong>Образец источника</strong><small>${draft.sampleLoaded?draft.samples.length+' записи для проверки':'Загрузите пример записей'}</small></div></li><li class="${report().covered===4?'done':''}"><span>${report().covered===4?'✓':'2'}</span><div><strong>Обязательные поля</strong><small>${report().covered} из 4 корректны во всём образце</small></div></li><li class="${draft.checked?'done':''}"><span>${draft.checked?'✓':'3'}</span><div><strong>Проверка результата</strong><small>${draft.checked?'Проверен текущий образец':'Посмотрите результат до запуска'}</small></div></li></ol><a class="btn primary" href="#feed/${draft.id}/mapping">Настроить маппинг →</a><div class="summary-note"><strong>Один фид — одна настройка</strong><p>Настройки и маппинг сохраняются вместе. Между вкладками можно переключаться без потери правок.</p></div></aside></div>`;}
function bindSettings(){main.querySelectorAll('[data-config]').forEach(el=>{const key=el.dataset.config;const update=()=>{draft[key]=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;if(['url','encoding'].includes(key))draft.sampleLoaded=false;mark();};if(key==='format'){el.onchange=()=>{const next=el.value;dialog('Изменить формат?',`<p>Образец и соответствия полей будут заменены пустой настройкой для ${fmt[next]}. Название и расписание сохранятся.</p>`,[{label:'Оставить текущий',action:()=>renderEditor()},{label:'Изменить формат',primary:true,action:()=>{draft.format=next;draft.mapping={};draft.samples=[];draft.sampleLoaded=false;draft.status='draft';undo=[];mark();renderEditor()}}]);document.querySelector('#dialog').addEventListener('close',()=>{if(document.getElementById('format'))document.getElementById('format').value=draft.format},{once:true});};}else if(el.type==='checkbox'||el.tagName==='SELECT')el.onchange=()=>{update();renderEditor()};else {el.oninput=update;el.onchange=()=>{if(key==='url'||key==='encoding')renderEditor()};}});main.querySelectorAll('[data-source-kind]').forEach(b=>b.onclick=()=>{if(draft.sourceKind!==b.dataset.sourceKind){draft.sourceKind=b.dataset.sourceKind;draft.sampleLoaded=false;draft.schedMode=draft.sourceKind==='file'?'manual':draft.schedMode;mark();renderEditor();}});main.querySelectorAll('[data-schedule-mode]').forEach(b=>b.onclick=()=>{draft.schedMode=b.dataset.scheduleMode;mark();renderEditor()});main.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{const d=Number(b.dataset.day);draft.days=draft.days.includes(d)?draft.days.filter(v=>v!==d):[...draft.days,d];mark();renderEditor()});const file=main.querySelector('#xml-file');if(file)file.onchange=()=>loadFile(file.files[0]);}
async function loadFile(file){if(!file)return;if(file.size>2*1024*1024){toast('Выберите XML-файл размером до 2 МБ');return;}try{const text=new TextDecoder(draft.encoding==='win1251'?'windows-1251':'utf-8').decode(await file.arrayBuffer());const doc=new DOMParser().parseFromString(text,'application/xml');if(doc.querySelector('parsererror'))throw Error('XML повреждён. Проверьте закрывающие теги и кодировку.');const nodes=Array.from(doc.querySelectorAll('Object,object,Ad,offer')).slice(0,20);if(!nodes.length)throw Error('Не найдены записи Object, Ad или offer. Проверьте формат фида.');const flatten=(node,prefix='',data={})=>{Array.from(node.attributes||[]).forEach(a=>data[(prefix?prefix+'.':'')+'@'+a.name]=a.value);const children=Array.from(node.children);if(!children.length&&prefix){if(Object.hasOwn(data,prefix))data[prefix]+=';'+node.textContent;else data[prefix]=node.textContent;}children.forEach(n=>flatten(n,prefix?prefix+'.'+n.tagName:n.tagName,data));return data;};draft.samples=nodes.map((n,i)=>{const data=flatten(n);return {_id:data.ExternalId||data.Id||data['@internal-id']||'Запись '+(i+1),_label:'Из загруженного файла',data};});draft.fileName=file.name;draft.sourceKind='file';draft.schedMode='manual';draft.sampleLoaded=true;sampleIndex=0;mark();renderEditor();toast('Файл разобран: '+draft.samples.length+' записей в образце');}catch(err){toast(err.message);}}
function action(name){if(busy&&['run','activate','pause'].includes(name))return;if(name==='discard')return dialog('Отменить изменения?',`<p>Настройки и маппинг вернутся к последнему сохранённому состоянию.</p>`,[{label:'Оставить правки'},{label:'Отменить изменения',danger:true,action:()=>{draft=JSON.parse(baseline);undo=[];renderEditor();toast('Восстановлена сохранённая версия')}}]);if(name==='pause'){draft.status='paused';mark();renderEditor();return toast('Импорт приостановлен в черновике. Сохраните изменения.');}if(name==='load-sample'){const load=()=>{draft.samples=clone(reference.formats[draft.format].samples);draft.sampleLoaded=true;draft.fileName=draft.sourceKind==='file'?draft.format+'-demo.xml':draft.fileName;sampleIndex=0;mark();renderEditor();toast('Загружен демонстрационный образец: 3 записи')};if(draft.fileName&&draft.sourceKind==='file')return dialog('Заменить загруженный образец?',`<p>Вместо файла будет использован демонстрационный образец ${fmt[draft.format]}. Маппинг сохранится.</p>`,[{label:'Отмена'},{label:'Заменить',primary:true,action:load}]);load();return;}if(name==='activate'||name==='run'){const errors=configErrors();if(errors.length){tab='settings';history.replaceState(null,'',`#feed/${draft.id}/settings`);currentHash=location.hash;renderEditor();showErrors(errors);return;}if(!draft.sampleLoaded){tab='settings';renderEditor();toast('Сначала загрузите образец фида');return;}const r=report();if(r.covered!==r.required){go(`#feed/${draft.id}/check`);toast('Исправьте обязательные поля во всём образце');return;}if(name==='activate'){draft.status='active';mark();if(save(true)){renderEditor();toast('Фид активирован в макете. Реальный импорт не запускается.')}return;}go(`#feed/${draft.id}/check`);busy=true;const runningDraft=draft;renderEditor();setTimeout(()=>{if(draft!==runningDraft){busy=false;return;}const bad=new Set(r.issues.map(i=>i.index)).size;draft.history=draft.history.slice(0,9);draft.history.unshift({time:new Date().toLocaleString('ru-RU'),total:draft.samples.length,success:draft.samples.length-bad,failed:bad});draft.errors=bad;draft.lastSync='Только что · демо';draft.status=bad?'error':'active';draft.checked=true;busy=false;if(save(true)){renderEditor();toast('Демоимпорт завершён: '+(draft.samples.length-bad)+' из '+draft.samples.length+' записей прошли проверку');}else renderEditor();},650);}}
function mappingHtml(r){if(!draft.sampleLoaded)return `<div class="panel empty"><h2>Сначала нужен образец фида</h2><p>На образце видны доступные поля и результат каждого преобразования.</p><button class="btn primary" data-action="load-sample">Загрузить демообразец ${fmt[draft.format]}</button><a class="btn" href="#feed/${draft.id}/settings">К источнику</a></div>`;return `<div class="mapping-toolbar"><div class="coverage"><strong>${r.covered}<span> / ${r.required}</span></strong><div>Обязательные поля<small>Проверены на ${draft.samples.length} записях</small></div></div><div class="row"><button class="btn" id="undo-map" ${!undo.length?'disabled':''}>↶ Отменить шаг</button><button class="btn" id="preset">Пресет ${fmt[draft.format]}</button><a class="btn primary" href="#feed/${draft.id}/check">Проверить образец →</a></div></div><div class="mapping-workspace"><aside class="field-sidebar panel"><div class="field-search"><input type="search" id="field-search" aria-label="Поиск полей" placeholder="Найти поле…" value="${e(fieldQuery)}"><select id="field-filter" aria-label="Фильтр полей">${options({all:'Все поля · '+fields.length,required:'Обязательные · 4',errors:'С ошибками · '+new Set(r.issues.map(i=>i.field.key)).size,mapped:'Сопоставленные',empty:'Не заполнены'},fieldFilter)}</select></div><div id="field-tree">${treeHtml(r)}</div></aside><div class="mapping-inspector" id="field-editor">${inspectorHtml()}</div></div>`;}
function treeHtml(r){return reference.tree.map(g=>{const list=g.fields.filter(f=>{const rr=r.results.find(x=>x.field.key===f.key);return (f.label+' '+f.key).toLowerCase().includes(fieldQuery.toLowerCase())&&(fieldFilter==='all'||fieldFilter==='required'&&f.required||fieldFilter==='errors'&&rr.traces.some(t=>t.error)||fieldFilter==='mapped'&&rr.traces.some(t=>!t.empty)||fieldFilter==='empty'&&rr.traces.every(t=>t.empty));});return list.length?`<section class="field-group"><h3>${g.group} <small>${list.length}</small></h3>${list.map(f=>{const rr=r.results.find(x=>x.field.key===f.key),bad=rr.traces.some(t=>t.error),mapped=rr.traces.some(t=>!t.empty);return `<button class="field-item" data-field="${f.key}" ${selected===f.key?'aria-current="true"':''}><span class="field-symbol ${bad?'error':mapped?'ok':''}" aria-label="${bad?'Ошибка':mapped?'Заполнено':'Не заполнено'}">${bad?'!':mapped?'✓':'—'}</span><span>${e(f.label)}${f.required?'<em> *</em>':''}<small>${e(f.key)}</small></span></button>`}).join('')}</section>`:''}).join('')||'<div class="empty small">Подходящих полей нет</div>';}
function inspectorHtml(){const f=fields.find(f=>f.key===selected),m=draft.mapping[selected]||{mode:'empty',source:'',const:'',steps:[]},sample=draft.samples[sampleIndex]||draft.samples[0],trace=run(f,m,sample.data);const paths=[...new Set(draft.samples.flatMap(s=>Object.keys(s.data)))];return `<div class="field-heading"><div><h2>${e(f.label)} ${f.required?'<span class="badge warn">Обязательное</span>':''}</h2><p><code>${f.key}</code><span>${types[f.type]}</span></p></div><label class="record-select">Запись образца<select id="sample-index">${draft.samples.map((s,i)=>`<option value="${i}" ${i===sampleIndex?'selected':''}>${i+1} / ${draft.samples.length} · ${e(s._id)}</option>`).join('')}</select></label></div><section class="panel source-panel"><h3><span class="step-label">1</span> Источник значения</h3><div class="segmented">${[['feed','Из фида'],['const','Постоянное значение'],['empty','Не заполнять']].map(([k,v])=>`<button data-mode="${k}" aria-pressed="${m.mode===k}">${v}</button>`).join('')}</div>${m.mode==='feed'?`<label class="field"><span>Поле в источнике</span><input list="source-paths" id="source-path" value="${e(m.source)}" placeholder="Выберите или введите путь"><datalist id="source-paths">${paths.map(p=>`<option value="${e(p)}">${e(present(sample.data[p]))}</option>`).join('')}</datalist></label><div class="raw-value"><span>В образце</span><code>${e(present(sample.data[m.source]))}</code></div>`:m.mode==='const'?`<label class="field"><span>Постоянное значение</span>${f.enumv?`<select id="constant">${options(Object.fromEntries(['',...f.enumv].map(x=>[x,x?(typeLabels[x]?typeLabels[x]+' · ':'')+x:'Выберите значение'])),m.const)}</select>`:`<input id="constant" value="${e(String(m.const??''))}" placeholder="Значение для всех записей">`}</label>`:`<p class="small muted">${f.required?'Это поле обязательно. Для активации задайте источник или постоянное значение.':'Поле будет пропущено. Его можно настроить позже.'}</p>`}</section><section class="panel transforms-panel"><div class="row between"><h3><span class="step-label">2</span> Преобразования</h3><span class="small muted">Выполняются сверху вниз</span></div><div class="steps">${m.steps.map((s,i)=>stepHtml(s,i,m.steps.length,trace)).join('')||'<p class="no-steps">Значение переносится как есть. Добавьте преобразование, если его нужно очистить или привести к нужному формату.</p>'}</div><button class="add-step" id="add-step">＋ Добавить преобразование</button></section><section class="panel preview-panel"><div class="row between"><h3><span class="step-label">3</span> Результат</h3><span class="badge ${trace.error?'error':trace.empty?'':'ok'}">${trace.error?'Нужна правка':trace.empty?'Не заполнено':'Корректно'}</span></div><div class="result-value ${trace.error?'has-error':''}"><code>${e(present(trace.final))}</code></div>${trace.error?`<p class="validation-error" role="status">${e(trace.error)}</p>`:''}<details class="all-records" open><summary>Все записи образца <span>${draft.samples.length}</span></summary><div class="table-scroll"><table><thead><tr><th>Запись</th><th>Исходное</th><th>Результат</th></tr></thead><tbody>${draft.samples.map((rec,i)=>{const t=run(f,m,rec.data);return `<tr class="${i===sampleIndex?'selected-row':''}"><td><button class="record-link" data-record="${i}">${e(rec._id)}</button></td><td><code>${e(present(m.mode==='const'?m.const:rec.data[m.source]))}</code></td><td><span class="${t.error?'error-text':''}">${t.error?'! ':''}${e(present(t.final))}</span>${t.error?`<small class="error-text">${e(t.error)}</small>`:''}</td></tr>`}).join('')}</tbody></table></div></details></section><details class="panel raw-panel"><summary>Поля исходной записи <span class="small muted">${Object.keys(sample.data).length}</span></summary><div class="raw-fields">${Object.entries(sample.data).map(([k,v])=>`<button data-raw-path="${e(k)}" title="Назначить источником поля ${e(f.label)}"><code>${e(k)}</code><span>${e(present(v))}</span><b>＋</b></button>`).join('')}</div></details>`;}
function paramInput(step,key,label,ctl='text',choices=[]){const value=step.params?.[key]??'';return `<label class="field"><span>${e(label)}</span>${ctl==='select'?`<select data-param="${key}" data-step="${step.id}">${options(Object.fromEntries(choices.map(x=>[x,typeLabels[x]||x])),value)}</select>`:ctl==='check'?`<input type="checkbox" data-param="${key}" data-step="${step.id}" ${value?'checked':''}>`:ctl==='textarea'?`<textarea data-param="${key}" data-step="${step.id}" rows="3" spellcheck="false">${e(String(value))}</textarea>`:`<input type="${ctl}" data-param="${key}" data-step="${step.id}" value="${e(String(value))}">`}</label>`;}
function stepHtml(s,i,total,trace){const definition=byType[s.type]||{name:s.type},p=s.params||{};let editor='';if(definition.editor==='dictionary'){const field=fields.find(f=>f.key===selected);editor=`<div class="dictionary-head"><span>Значение из фида</span><span>Наше значение</span></div>${(p.rows||[]).map((row,index)=>`<div class="dictionary-row"><input aria-label="Значение фида ${index+1}" data-dict="from" data-step="${s.id}" data-row="${index}" value="${e(row.from)}"><span>→</span>${field.enumv?`<select aria-label="Наше значение ${index+1}" data-dict="to" data-step="${s.id}" data-row="${index}">${options(Object.fromEntries(['',...field.enumv].map(x=>[x,x?(typeLabels[x]?typeLabels[x]+' · ':'')+x:'Выберите'])),row.to)}</select>`:`<input aria-label="Наше значение ${index+1}" data-dict="to" data-step="${s.id}" data-row="${index}" value="${e(row.to)}">`}<button class="mini-btn" data-dict-remove="${index}" data-step="${s.id}" aria-label="Удалить соответствие ${index+1}">×</button></div>`).join('')}<button class="btn text" data-dict-add="${s.id}">＋ Добавить соответствие</button>${paramInput(s,'fallback','Если соответствие не найдено (пусто = ошибка)')}${paramInput(s,'ci','Без учёта регистра','check')}`;const mapped=fieldMapping(),unknown=[...new Set(draft.samples.map(rec=>rec.data[mapped.source]).filter(v=>v!=null&&v!==''&&!(p.rows||[]).some(row=>p.ci===false?String(row.from)===String(v):String(row.from).toLowerCase()===String(v).toLowerCase())))];if(unknown.length)editor+=`<div class="notice warn"><strong>Новые значения в образце</strong><div class="row">${unknown.map(v=>`<button class="chip" data-unknown="${e(String(v))}" data-step="${s.id}">＋ ${e(String(v))}</button>`).join('')}</div></div>`;}else if(definition.editor==='boolean')editor=paramInput(s,'truthy','Значения «Да», через запятую')+paramInput(s,'falsy','Значения «Нет», через запятую')+paramInput(s,'fallback','Если значение не распознано','select',['error','true','false']);else if(definition.editor==='math'||definition.editor==='expression')editor=paramInput(s,definition.editor==='math'?'expr':'code','Формула','textarea')+'<p class="small muted">value — текущее значение, src(\'Путь\') — другое поле. Доступны арифметика, сравнения, условие ? :, num(), round(), len(). Например: num(value) * 100.</p>';else if(definition.editor==='template')editor=paramInput(s,'template','Шаблон','textarea')+'<p class="small muted">Используйте {{ value }} и {{ field:City }} для подстановки.</p>';else editor=(definition.spec||[]).map(spec=>paramInput(s,spec.key,spec.label,spec.ctl,spec.options)).join('');const output=trace.stages.find(t=>t.id===s.id);return `<details class="transform ${s.enabled===false?'disabled-step':''}" ${i===0?'open':''}><summary><span class="step-order">${i+1}</span><span>${e(definition.name)}</span><span class="small muted">${s.enabled===false?'Выключено':'Настроить'}</span></summary><div class="transform-content"><p class="small muted">${e(definition.desc||'')}</p>${editor}${output?`<div class="step-output"><span>После шага</span><code>${e(present(output.value))}</code></div>`:''}<div class="step-actions"><label><input type="checkbox" data-step-enabled="${s.id}" ${s.enabled!==false?'checked':''}> Включено</label><div class="row"><button class="mini-btn" data-step-up="${s.id}" aria-label="Поднять шаг ${i+1}" ${i===0?'disabled':''}>↑</button><button class="mini-btn" data-step-down="${s.id}" aria-label="Опустить шаг ${i+1}" ${i===total-1?'disabled':''}>↓</button><button class="mini-btn error-text" data-step-remove="${s.id}" aria-label="Удалить шаг ${i+1}">Удалить</button></div></div></div></details>`;}
function bindTree(){main.querySelectorAll('[data-field]').forEach(b=>b.onclick=()=>{selected=b.dataset.field;renderEditor();document.querySelector('#field-editor').scrollIntoView({block:'nearest'})});}
function bindMapping(){bindTree();main.querySelector('#field-search').oninput=ev=>{fieldQuery=ev.target.value;main.querySelector('#field-tree').innerHTML=treeHtml(report());bindTree()};main.querySelector('#field-filter').onchange=ev=>{fieldFilter=ev.target.value;main.querySelector('#field-tree').innerHTML=treeHtml(report());bindTree()};main.querySelector('#undo-map').onclick=()=>{if(undo.length){draft.mapping=undo.pop();mark();renderEditor();toast('Последняя правка маппинга отменена')}};main.querySelector('#preset').onclick=()=>dialog('Применить пресет '+fmt[draft.format]+'?',`<p>Можно заполнить только пустые поля или заменить весь маппинг. Изменение можно отменить.</p>`,[{label:'Отмена'},{label:'Только пустые',primary:true,action:()=>editMapping(()=>{for(const [key,m]of Object.entries(reference.formats[draft.format].preset)){if(!draft.mapping[key]||draft.mapping[key].mode==='empty')draft.mapping[key]=clone(m)}})},{label:'Заменить всё',action:()=>editMapping(()=>draft.mapping=clone(reference.formats[draft.format].preset))}]);main.querySelector('#sample-index').onchange=ev=>{sampleIndex=Number(ev.target.value);renderEditor()};main.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>{sampleIndex=Number(b.dataset.record);renderEditor()});main.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>editMapping(()=>fieldMapping().mode=b.dataset.mode));const source=main.querySelector('#source-path');if(source)source.onchange=()=>editMapping(()=>fieldMapping().source=source.value.trim());const constant=main.querySelector('#constant');if(constant)constant.onchange=()=>editMapping(()=>{const f=fields.find(f=>f.key===selected),v=constant.value;fieldMapping().const=f.type==='number'&&v!==''?Number(v):f.type==='bool'&&['true','false'].includes(v)?v==='true':v});main.querySelectorAll('[data-raw-path]').forEach(b=>b.onclick=()=>editMapping(()=>Object.assign(fieldMapping(),{mode:'feed',source:b.dataset.rawPath})));main.querySelector('#add-step').onclick=addStepDialog;const step=id=>fieldMapping().steps.find(s=>s.id===id);main.querySelectorAll('[data-param]').forEach(el=>el.onchange=()=>editMapping(()=>{step(el.dataset.step).params[el.dataset.param]=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value}));main.querySelectorAll('[data-dict]').forEach(el=>el.onchange=()=>editMapping(()=>{step(el.dataset.step).params.rows[Number(el.dataset.row)][el.dataset.dict]=el.value}));main.querySelectorAll('[data-dict-remove]').forEach(b=>b.onclick=()=>editMapping(()=>step(b.dataset.step).params.rows.splice(Number(b.dataset.dictRemove),1)));main.querySelectorAll('[data-dict-add]').forEach(b=>b.onclick=()=>editMapping(()=>step(b.dataset.dictAdd).params.rows.push({from:'',to:''})));main.querySelectorAll('[data-unknown]').forEach(b=>b.onclick=()=>editMapping(()=>step(b.dataset.step).params.rows.push({from:b.dataset.unknown,to:''})));main.querySelectorAll('[data-step-enabled]').forEach(el=>el.onchange=()=>editMapping(()=>step(el.dataset.stepEnabled).enabled=el.checked));main.querySelectorAll('[data-step-remove]').forEach(b=>b.onclick=()=>editMapping(()=>fieldMapping().steps=fieldMapping().steps.filter(s=>s.id!==b.dataset.stepRemove)));for(const direction of ['up','down'])main.querySelectorAll(`[data-step-${direction}]`).forEach(b=>b.onclick=()=>editMapping(()=>{const arr=fieldMapping().steps,i=arr.findIndex(s=>s.id===b.dataset[direction==='up'?'stepUp':'stepDown']),to=i+(direction==='up'?-1:1);if(to>=0&&to<arr.length)[arr[i],arr[to]]=[arr[to],arr[i]];}));}
function addStepDialog(){const dlg=dialog('Добавить преобразование',`<label class="field"><span>Найти преобразование</span><input type="search" id="transform-search" placeholder="Число, словарь, текст…"></label><div id="transform-catalog"></div>`,[{label:'Закрыть'}]);const draw=(query='')=>{dlg.querySelector('#transform-catalog').innerHTML=reference.catalog.map(g=>{const list=g.items.filter(s=>(s.name+' '+s.desc).toLowerCase().includes(query.toLowerCase()));return list.length?`<h3 class="catalog-heading">${g.group}</h3>${list.map(t=>`<button class="catalog-item" data-transform="${t.type}" ${['regex','geocode'].includes(t.type)?'disabled':''}><strong>${e(t.name)}</strong><small>${e(t.desc)}${['regex','geocode'].includes(t.type)?' · Недоступно в макете':''}</small><span>＋</span></button>`).join('')}`:''}).join('')||'<p>Ничего не найдено</p>';dlg.querySelectorAll('[data-transform]').forEach(b=>b.onclick=()=>{dlg.close();editMapping(()=>{const def=byType[b.dataset.transform];fieldMapping().steps.push({id:crypto.randomUUID(),type:def.type,enabled:true,params:clone(def.defaults||{})})});});};draw();dlg.querySelector('#transform-search').oninput=ev=>draw(ev.target.value);}
function checkHtml(r){if(!draft.sampleLoaded)return `<div class="panel empty"><h2>Нет образца для проверки</h2><p>Загрузите демообразец или свой XML-файл на вкладке источника.</p><a class="btn primary" href="#feed/${draft.id}/settings">Настроить источник</a></div>`;const invalid=new Set(r.issues.map(x=>x.index)).size,blocked=r.required-r.covered;return `<div class="check-heading"><div><h2>Результат на образце</h2><p>Проверяются ${draft.samples.length} записи, а не весь фид.</p></div><button id="validate" class="btn primary">✓ Проверить образец</button></div>${draft.errors&&!draft.history.length?`<div class="notice warn"><strong>В последнем импорте было ${draft.errors} ошибок</strong><p>Это исторический показатель из исходного макета. Ниже — отдельная проверка текущего образца.</p></div>`:''}<div class="check-stats"><div class="panel"><span>Записей в образце</span><strong>${draft.samples.length}</strong></div><div class="panel"><span>Готовы к импорту</span><strong class="ok-text">${draft.samples.length-invalid}</strong></div><div class="panel"><span>Требуют исправления</span><strong class="${invalid?'error-text':''}">${invalid}</strong></div></div><div class="notice ${blocked?'error':'success'}"><strong>${blocked?`Не заполнены корректно ${blocked} обязательных поля`:'Обязательные поля корректны на всём образце'}</strong><p>${blocked?'Настройте поля, перечисленные ниже, перед активацией фида.':r.issues.length?'Есть ошибки в других полях. Исправьте их, чтобы записи не были пропущены.':'Можно сохранить настройки и выполнить демоимпорт.'}</p></div>${r.issues.length?`<section class="panel issues-panel"><div class="panel-title"><h3>Что нужно исправить</h3><span class="badge error">${r.issues.length}</span></div>${r.results.filter(rr=>rr.traces.some(t=>t.error)).sort((a,b)=>Number(b.field.required)-Number(a.field.required)).map(rr=>{const first=rr.traces.findIndex(t=>t.error),count=rr.traces.filter(t=>t.error).length;return `<div class="issue-row"><span class="issue-mark">!</span><div><strong>${e(rr.field.label)}${rr.field.required?' · обязательное':''}</strong><p>${e(rr.traces[first].error)}</p><small>Затронуто записей: ${count} · ${e(draft.samples[first]._id)}</small></div><button class="btn" data-fix="${rr.field.key}" data-record="${first}">Исправить →</button></div>`}).join('')}</section>`:''}<section class="panel sample-results"><div class="panel-title"><h3>Предпросмотр объявлений</h3><span class="small muted">${draft.checked?'Проверено':'Рассчитано по текущим настройкам'}</span></div><div class="table-scroll"><table><thead><tr><th>Запись</th><th>Заголовок</th><th>Цена</th><th>Тип сделки</th><th>Результат</th></tr></thead><tbody>${draft.samples.map((rec,index)=>{const val=key=>run(fields.find(f=>f.key===key),draft.mapping[key],rec.data).final,issues=r.issues.filter(x=>x.index===index);return `<tr><td><code>${e(rec._id)}</code></td><td>${e(present(val('title')))}</td><td class="nowrap">${typeof val('price')==='number'?nf(val('price')):e(present(val('price')))}</td><td>${e(typeLabels[val('deal_type')]||present(val('deal_type')))}</td><td><span class="badge ${issues.length?'error':'ok'}">${issues.length?'Ошибок: '+issues.length:'Готова'}</span></td></tr>`}).join('')}</tbody></table></div></section>${draft.history.length?`<section class="panel history-panel"><div class="panel-title"><h3>Последний демоимпорт</h3><span class="small muted">${e(draft.history[0].time)}</span></div><p>Обработано ${draft.history[0].total} · Успешно ${draft.history[0].success} · Пропущено ${draft.history[0].failed}</p><p class="small muted">Это локальная проверка. Объявления в рабочем каталоге не изменялись.</p></section>`:''}${busy?'<div class="notice" role="status">Выполняется демонстрационная проверка…</div>':''}`;}
function bindCheck(){main.querySelectorAll('[data-fix]').forEach(b=>b.onclick=()=>{selected=b.dataset.fix;sampleIndex=Number(b.dataset.record);fieldFilter='all';fieldQuery='';go(`#feed/${draft.id}/mapping`)});const validate=main.querySelector('#validate');if(validate)validate.onclick=()=>{draft.checked=true;renderEditor();toast(report().issues.length?'Проверка завершена. Найдено ошибок: '+report().issues.length:'Все записи образца корректны');};}
const originalList=renderList;
renderList=()=>{main.className='';originalList();};
const originalBindMapping=bindMapping;
bindMapping=()=>{
 originalBindMapping();
 main.querySelectorAll('#source-path,#constant,input[data-param],textarea[data-param],input[data-dict]').forEach(el=>{
  if(el.type==='checkbox'||el.tagName==='SELECT')return;
  const update=el.onchange;el.onchange=null;
  el.oninput=()=>{
   const start=el.selectionStart,end=el.selectionEnd,scroll=main.querySelector('.field-sidebar').scrollTop;
   const selector=el.id?'#'+CSS.escape(el.id):el.dataset.dict?`[data-step="${CSS.escape(el.dataset.step)}"][data-row="${el.dataset.row}"][data-dict="${el.dataset.dict}"]`:`[data-step="${CSS.escape(el.dataset.step)}"][data-param="${el.dataset.param}"]`;
   update();
   const replacement=main.querySelector(selector);
   if(replacement){replacement.closest('details')?.setAttribute('open','');replacement.focus({preventScroll:true});if(start!==null&&['text','search','url','tel','password','textarea'].includes(replacement.type)&&typeof replacement.setSelectionRange==='function')replacement.setSelectionRange(start,end);}
   main.querySelector('.field-sidebar').scrollTop=scroll;
  };
 });
};
route();
